Collect all comparison assertions, then emit a single conjunctive negation:
# Replace the per-comparison negation loop with:
    claim_parts: List[str] = []
    for var_name, op, value_str in comparisons:
        try:
            value = float(value_str)
        except ValueError:
            continue
        if var_name not in declared:
            declarations.append(f"(declare-const {var_name} Real)")
            declared.add(var_name)
        smt_op = {">=": ">=", "<=": "<=", ">": ">", "<": "<",
                   "==": "=", "!=": "distinct"}[op]
        if var_name in constants and isinstance(constants[var_name], (int, float)):
            grounded = float(constants[var_name])
            grounding_assert = f"(assert (= {var_name} {grounded}))"
            if grounding_assert not in assertions:
                assertions.append(grounding_assert)
            has_grounding = True
        claim_parts.append(f"({smt_op} {var_name} {value})")

    if not claim_parts:
        return None

    # Single conjunctive negation: check if ALL conditions can be violated simultaneously
    if len(claim_parts) == 1:
        assertions.append(f"(assert (not {claim_parts[0]}))")
    else:
        conjunction = " ".join(claim_parts)
        assertions.append(f"(assert (not (and {conjunction})))")

